def close_order(order_id: str, *, store: OrderStore) -> Receipt:
    order = store.load(order_id)
    rate = 0.2 if order.country == "GB" else 0.0
    if order.total > 1000:
        rate -= 0.05
    total = order.total * (1 + rate)
    store.save(replace(order, status="closed", total=total))
    return Receipt(order_id, total)

def save_order(order: Order, *, store: OrderStore) -> None:
    if order.total < 0 or not order.lines:
        raise ValueError("an order needs lines and a non-negative total")
    store.save(order)
